CREATE OR REPLACE FUNCTION app_private.get_admin_sellers_page(_from date,_to date,_page integer DEFAULT 0,_search text DEFAULT '',_state text DEFAULT 'all',_risk text DEFAULT 'all',_sort text DEFAULT 'volume',_selling_only boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_from timestamptz; v_to timestamptz; result jsonb;
BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
IF _from IS NULL OR _to IS NULL OR _to<_from OR _to-_from>365 OR _page IS NULL OR _page<0 OR _page>100000 OR _search IS NULL OR length(_search)>120 OR _state IS NULL OR _state NOT IN ('all','white','black','unset','kyc','frozen','blocked','rejected','approved') OR _risk IS NULL OR _risk NOT IN ('all','med','chargeback','refund','any') OR _sort IS NULL OR _sort NOT IN ('volume','sales','med','chargeback','refund','newest') OR _selling_only IS NULL THEN RAISE EXCEPTION 'Invalid seller filters' USING ERRCODE='22023'; END IF;
v_from:=_from::timestamp AT TIME ZONE 'America/Sao_Paulo'; v_to:=(_to+1)::timestamp AT TIME ZONE 'America/Sao_Paulo';
WITH sellers AS MATERIALIZED (
SELECT p.user_id,p.full_name,p.email,p.account_status,p.seller_type,p.balance_frozen,p.created_at FROM public.profiles p WHERE NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.user_id AND r.role IN ('admin','employee','manager','partner'))
), tx AS MATERIALIZED (
SELECT t.id,t.user_id,t.amount,t.status,t.payment_method,t.status IN ('approved','paid','completed') AS paid FROM public.transactions t JOIN sellers s ON s.user_id=t.user_id WHERE t.created_at>=v_from AND t.created_at<v_to AND NOT coalesce(t.is_simulated,false)
), st AS (SELECT user_id,count(*) attempts,count(*) FILTER(WHERE paid) sales,coalesce(sum(amount) FILTER(WHERE paid),0) volume FROM tx GROUP BY user_id), cb AS MATERIALIZED (
SELECT DISTINCT t.id,t.user_id,t.amount FROM public.disputes d JOIN public.transactions t ON t.id=d.transaction_id JOIN sellers s ON s.user_id=t.user_id WHERE d.type='chargeback' AND d.created_at>=v_from AND d.created_at<v_to AND NOT coalesce(t.is_simulated,false)
UNION SELECT id,user_id,amount FROM tx WHERE status IN ('chargeback','chargedback','charged_back') AND payment_method IS DISTINCT FROM 'pix'
), med AS MATERIALIZED (SELECT d.seller_user_id,count(*) count,coalesce(sum(d.amount),0) amount FROM public.disputes d JOIN public.transactions t ON t.id=d.transaction_id JOIN sellers s ON s.user_id=d.seller_user_id WHERE d.type IN ('medpix','pre_med_pix') AND d.created_at>=v_from AND d.created_at<v_to AND NOT coalesce(t.is_simulated,false) GROUP BY d.seller_user_id), rf AS MATERIALIZED (SELECT r.seller_user_id,count(*) count,coalesce(sum(r.amount),0) amount FROM public.refund_requests r JOIN public.transactions t ON t.id=r.transaction_id JOIN sellers s ON s.user_id=r.seller_user_id WHERE r.status='confirmed' AND r.decided_at>=v_from AND r.decided_at<v_to AND NOT coalesce(t.is_simulated,false) GROUP BY r.seller_user_id), rows AS MATERIALIZED (
SELECT s.*,coalesce(st.attempts,0) attempts,coalesce(st.sales,0) sales,coalesce(st.volume,0) volume,coalesce(med.count,0) med,coalesce(med.amount,0) med_amount,coalesce(c.count,0) chargebacks,coalesce(c.amount,0) chargeback_amount,coalesce(rf.count,0) refunds,coalesce(rf.amount,0) refund_amount FROM sellers s LEFT JOIN st ON st.user_id=s.user_id LEFT JOIN med ON med.seller_user_id=s.user_id LEFT JOIN rf ON rf.seller_user_id=s.user_id LEFT JOIN (SELECT user_id,count(*) count,sum(amount) amount FROM cb GROUP BY user_id) c ON c.user_id=s.user_id
), filtered AS MATERIALIZED (
SELECT * FROM rows WHERE (_search='' OR position(lower(btrim(_search)) in lower(coalesce(full_name,'')||' '||coalesce(email,'')||' '||user_id::text))>0) AND (NOT _selling_only OR sales>0) AND (_state='all' OR (_state IN ('white','black') AND seller_type=_state) OR (_state='unset' AND seller_type IS NULL) OR (_state='kyc' AND account_status IN ('pending','pending_review')) OR (_state='frozen' AND balance_frozen) OR (_state IN ('blocked','rejected','approved') AND account_status=_state)) AND (_risk='all' OR (_risk='med' AND med>0) OR (_risk='chargeback' AND chargebacks>0) OR (_risk='refund' AND refunds>0) OR (_risk='any' AND med+chargebacks+refunds>0))
), paged AS (SELECT * FROM filtered ORDER BY CASE WHEN _sort='volume' THEN volume END DESC,CASE WHEN _sort='sales' THEN sales END DESC,CASE WHEN _sort='med' THEN med END DESC,CASE WHEN _sort='chargeback' THEN chargebacks END DESC,CASE WHEN _sort='refund' THEN refunds END DESC,CASE WHEN _sort='newest' THEN created_at END DESC,user_id LIMIT 25 OFFSET _page*25)
SELECT jsonb_build_object('rows',(SELECT coalesce(jsonb_agg(to_jsonb(paged)),'[]'::jsonb) FROM paged),'total',(SELECT count(*) FROM filtered),'page',_page,'page_size',25,'summary',jsonb_build_object('registered',(SELECT count(*) FROM rows),'selling',(SELECT count(*) FROM rows WHERE sales>0),'kyc',(SELECT count(*) FROM rows WHERE account_status IN ('pending','pending_review')),'volume',(SELECT coalesce(sum(volume),0) FROM rows),'med',(SELECT coalesce(sum(med),0) FROM rows),'chargebacks',(SELECT coalesce(sum(chargebacks),0) FROM rows)),'checked_at',now()) INTO result;
RETURN result;
END $$;
REVOKE ALL ON FUNCTION app_private.get_admin_sellers_page(date,date,integer,text,text,text,text,boolean) FROM PUBLIC,anon;
GRANT USAGE ON SCHEMA app_private TO authenticated;
GRANT EXECUTE ON FUNCTION app_private.get_admin_sellers_page(date,date,integer,text,text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_admin_sellers_page(_from date,_to date,_page integer DEFAULT 0,_search text DEFAULT '',_state text DEFAULT 'all',_risk text DEFAULT 'all',_sort text DEFAULT 'volume',_selling_only boolean DEFAULT false) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$ SELECT app_private.get_admin_sellers_page(_from,_to,_page,_search,_state,_risk,_sort,_selling_only); $$;
REVOKE ALL ON FUNCTION public.get_admin_sellers_page(date,date,integer,text,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_admin_sellers_page(date,date,integer,text,text,text,text,boolean) TO authenticated;